import pandas as pd
import json

# List all source file paths
source_files = [
    "autopipeline-benchmarks/github-pipelines/length9_16/test_0.csv",
    "autopipeline-benchmarks/github-pipelines/length9_16/test_1.csv",
    "autopipeline-benchmarks/github-pipelines/length9_16/test_2.csv",
    "autopipeline-benchmarks/github-pipelines/length9_16/test_3.csv",
    "autopipeline-benchmarks/github-pipelines/length9_16/test_4.csv",
    "autopipeline-benchmarks/github-pipelines/length9_16/test_5.csv",
    "autopipeline-benchmarks/github-pipelines/length9_16/test_6.csv",
    "autopipeline-benchmarks/github-pipelines/length9_16/test_7.csv",
    "autopipeline-benchmarks/github-pipelines/length9_16/test_8.csv",
]

def normalize_coordinates(coord):
    """
    Convert coordinates column to string representation.
    If NaN, return NaN.
    If dict (GeoJSON Point), convert to string of coordinates list.
    Else, convert to string.
    """
    if pd.isna(coord):
        return pd.NA
    if isinstance(coord, str):
        # Try to parse JSON string if possible
        try:
            parsed = json.loads(coord)
            if isinstance(parsed, dict) and 'coordinates' in parsed:
                return str(parsed['coordinates'])
            else:
                return str(coord)
        except Exception:
            return str(coord)
    if isinstance(coord, dict):
        if 'coordinates' in coord:
            return str(coord['coordinates'])
        else:
            return str(coord)
    return str(coord)

def normalize_hashtags(hashtags):
    """
    Convert hashtags column to string representation.
    The source hashtags column is either:
    - empty list []
    - list of dicts [{'text': 'tag', 'indices': [...]}, ...]
    We convert it to a string list of hashtag texts, e.g. "['tag1', 'tag2']"
    """
    if pd.isna(hashtags):
        return "[]"
    if isinstance(hashtags, str):
        # Try to parse JSON string
        try:
            parsed = json.loads(hashtags)
            if isinstance(parsed, list):
                texts = [h.get('text', '') for h in parsed if isinstance(h, dict) and 'text' in h]
                return str(texts)
            else:
                return "[]"
        except Exception:
            # If not JSON, return as is
            return hashtags
    if isinstance(hashtags, list):
        texts = [h.get('text', '') for h in hashtags if isinstance(h, dict) and 'text' in h]
        return str(texts)
    return "[]"

# Read all source files into a list of DataFrames
dfs = []
for file_path in source_files:
    df = pd.read_csv(file_path, index_col=0)
    # Normalize columns to target schema and types
    # Columns: ['created_at', 'text', 'coordinates', 'hashtags']
    # created_at and text are strings, coordinates string, hashtags string (list string)
    # Ensure columns exist and in correct order
    df = df[['created_at', 'text', 'coordinates', 'hashtags']]

    # Normalize coordinates column
    df['coordinates'] = df['coordinates'].apply(normalize_coordinates)

    # Normalize hashtags column
    df['hashtags'] = df['hashtags'].apply(normalize_hashtags)

    # Ensure created_at and text are strings (some might be read as other types)
    df['created_at'] = df['created_at'].astype(str)
    df['text'] = df['text'].astype(str)

    dfs.append(df)

# Concatenate all source DataFrames (UNION)
target_df = pd.concat(dfs, ignore_index=True)

# Write the result to the target CSV file
target_df.to_csv("autopipeline-benchmarks/github-pipelines/length9_16/target_multisource_cot.csv", index=False)
